import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, MeshStandardMaterial } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};
  root.userData.cleanup = cleanup;

  let glbScene = null;
  let hoverTimeline = null;
  let pressTimeline = null;

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbScene = gltf.scene;
    root.add(glbScene);

    // Scale to fit card bounds (~1.5 units tall)
    const box = new ctx.THREE.Box3().setFromObject(glbScene);
    const size = box.getSize(new ctx.THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);
    const scale = 1.2 / maxDim;
    glbScene.scale.multiplyScalar(scale);

    // Center geometry
    const center = box.getCenter(new ctx.THREE.Vector3());
    glbScene.position.copy(center).multiplyScalar(-scale);
  });

  // Hover interaction: rise-in lift
  const onHoverStart = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
  };

  const onHoverEnd = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: -0.2,
      duration: 0.9,
      ease: 'power4.out'
    }, 0);
  };

  // Click interaction: press-down
  const onClick = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);
    pressTimeline.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power4.out'
    }, 0.12);

    // Emit selection event
    ctx.emit('navigate', { to: 'hub-home.select' });
  };

  root.userData.handlers.onHoverStart = onHoverStart;
  root.userData.handlers.onHoverEnd = onHoverEnd;
  root.userData.handlers.onClick = onClick;

  // Apply scene position from config
  if (config.scenePosition) {
    root.position.copy(config.scenePosition);
  }

  function cleanup() {
    if (hoverTimeline) {
      hoverTimeline.kill();
      hoverTimeline = null;
    }
    if (pressTimeline) {
      pressTimeline.kill();
      pressTimeline = null;
    }
    if (glbScene) {
      glbScene.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  }

  return root;
}
